const crypto = require('crypto');

// Signs a call to Convex: HMAC-SHA256 over "timestamp.METHOD.path.body" (see README, Signing).
function signForConvex(path, payload) {
  const secret = $env.LENDLOOP_CONVEX_API_SECRET;
  const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;
  if (!secret || !baseUrl) throw new Error('LENDLOOP_CONVEX_API_SECRET or LENDLOOP_CONVEX_SITE_URL is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const mac = crypto.createHmac('sha256', secret).update(timestamp + '.POST.' + path + '.' + body).digest('hex');
  return { url: baseUrl + path, body, timestamp, signature: 'v1=' + mac };
}

return [{ json: signForConvex('/automation/overdue', {}) }];

// One item per overdue loan. No loans means nothing downstream runs.
const { asOf, loans } = $input.first().json;
console.log('[lendloop] overdue run ' + asOf + ': ' + loans.length + ' loan(s) need a reminder');
return loans.map((loan) => ({ json: { ...loan, asOf } }));

// Mock delivery: logs the reminder instead of sending an email.
const loan = $json;
const text = loan.borrower.displayName + ', the ' + loan.toolName + ' was due back on ' + loan.endDate
  + ' (' + loan.daysOverdue + ' day(s) ago). Please return it or contact the owner in LendLoop.';
console.log('[lendloop] reminder to=' + loan.borrower.clerkUserId + ' loan=' + loan.requestId + ': ' + text);
return { json: { requestId: loan.requestId, day: loan.asOf, channel: 'log' } };

const crypto = require('crypto');

// Signs a call to Convex: HMAC-SHA256 over "timestamp.METHOD.path.body" (see README, Signing).
function signForConvex(path, payload) {
  const secret = $env.LENDLOOP_CONVEX_API_SECRET;
  const baseUrl = $env.LENDLOOP_CONVEX_SITE_URL;
  if (!secret || !baseUrl) throw new Error('LENDLOOP_CONVEX_API_SECRET or LENDLOOP_CONVEX_SITE_URL is not set');
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const mac = crypto.createHmac('sha256', secret).update(timestamp + '.POST.' + path + '.' + body).digest('hex');
  return { url: baseUrl + path, body, timestamp, signature: 'v1=' + mac };
}

// Convex keys the write-back on (loan, day), so a retry or a second run records it once.
return { json: signForConvex('/automation/reminders', { requestId: $json.requestId, day: $json.day }) };

const counts = {};
for (const item of $input.all()) counts[item.json.status] = (counts[item.json.status] || 0) + 1;
console.log('[lendloop] reminder write-backs: ' + JSON.stringify(counts));
return [{ json: { reminders: $input.all().length, ...counts } }];
